layout='<LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="#020A1A" android:orientation="vertical"><TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="OTG FLASHER v2 BOOT/RECOVERY/SYSTEM/VENDOR/USERDATA" android:textColor="#00D4FF" android:gravity="center" android:padding="10dp" android:textStyle="bold"/><TextView android:id="@+id/tvUsb" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="USB: No OTG" android:textColor="#FFAA00" android:padding="8dp"/><TextView android:id="@+id/tvPath" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="No file" android:textColor="#888" android:padding="8dp"/><ScrollView android:layout_width="match_parent" android:layout_height="match_parent"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:padding="10dp"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal"><Button android:id="@+id/btnPick" android:layout_width="0dp" android:layout_weight="1" android:layout_height="46dp" android:text="PICK IMG" android:layout_margin="3dp"/><Button android:id="@+id/btnAdb" android:layout_width="0dp" android:layout_weight="1" android:layout_height="46dp" android:text="ADB" android:background="@drawable/bg_btn_cyan" android:layout_margin="3dp"/><Button android:id="@+id/btnFastboot" android:layout_width="0dp" android:layout_weight="1" android:layout_height="46dp" android:text="FASTBOOT" android:background="@drawable/bg_btn_orange" android:layout_margin="3dp"/></LinearLayout><Button android:id="@+id/btnBoot" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH TO BOOT" android:background="@drawable/bg_btn_cyan" android:layout_margin="3dp"/><Button android:id="@+id/btnRecovery" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH TO RECOVERY" android:background="@drawable/bg_btn_cyan" android:layout_margin="3dp"/><Button android:id="@+id/btnSystem" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH TO SYSTEM" android:background="@drawable/bg_btn_cyan" android:layout_margin="3dp"/><Button android:id="@+id/btnVendor" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH TO VENDOR" android:background="@drawable/bg_btn_cyan" android:layout_margin="3dp"/><Button android:id="@+id/btnUserdata" android:layout_width="match_parent" android:layout_height="50dp" android:text="FLASH TO USERDATA" android:background="@drawable/bg_btn_orange" android:layout_margin="3dp"/><Button android:id="@+id/btnVbmeta" android:layout_width="match_parent" android:layout_height="44dp" android:text="VBMETA DISABLE" android:background="@drawable/bg_btn_orange" android:layout_margin="3dp"/><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal"><Button android:id="@+id/btnUnlock" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:text="UNLOCK" android:layout_margin="3dp"/><Button android:id="@+id/btnWipe" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:text="WIPE" android:background="@drawable/bg_btn_red" android:layout_margin="3dp"/><Button android:id="@+id/btnReboot" android:layout_width="0dp" android:layout_weight="1" android:layout_height="44dp" android:text="REBOOT" android:background="@drawable/bg_btn_red" android:layout_margin="3dp"/></LinearLayout><TextView android:id="@+id/tvLog" android:layout_width="match_parent" android:layout_height="350dp" android:background="#000000" android:text="> Ready" android:textColor="#00FF88" android:fontFamily="monospace" android:padding="8dp" android:layout_marginTop="8dp"/></LinearLayout></ScrollView></LinearLayout>'
open("app/src/main/res/layout/activity_main.xml","w").write('<?xml version="1.0" encoding="utf-8"?>'+layout)
java='package com.otgflasher.pro; import android.app.PendingIntent; import android.content.*; import android.hardware.usb.*; import android.net.Uri; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import java.io.*; import java.util.HashMap; public class MainActivity extends AppCompatActivity { TextView tvLog, tvUsb, tvPath; String selectedPath=""; UsbManager usbManager; static final String ACTION_USB="com.otgflasher.pro.USB"; @Override protected void onCreate(Bundle b){ super.onCreate(b); setContentView(R.layout.activity_main); tvLog=findViewById(R.id.tvLog); tvUsb=findViewById(R.id.tvUsb); tvPath=findViewById(R.id.tvPath); usbManager=(UsbManager)getSystemService(Context.USB_SERVICE); findViewById(R.id.btnPick).setOnClickListener(v->pickFile()); findViewById(R.id.btnAdb).setOnClickListener(v->exec("adb devices")); findViewById(R.id.btnFastboot).setOnClickListener(v->exec("fastboot devices")); findViewById(R.id.btnBoot).setOnClickListener(v->flash("boot")); findViewById(R.id.btnRecovery).setOnClickListener(v->flash("recovery")); findViewById(R.id.btnSystem).setOnClickListener(v->flash("system")); findViewById(R.id.btnVendor).setOnClickListener(v->flash("vendor")); findViewById(R.id.btnUserdata).setOnClickListener(v->flash("userdata")); findViewById(R.id.btnVbmeta).setOnClickListener(v->exec("fastboot --disable-verity --disable-verification flash vbmeta "+(selectedPath.isEmpty()?"vbmeta.img":selectedPath))); findViewById(R.id.btnUnlock).setOnClickListener(v->exec("fastboot flashing unlock")); findViewById(R.id.btnWipe).setOnClickListener(v->exec("fastboot -w")); findViewById(R.id.btnReboot).setOnClickListener(v->exec("fastboot reboot")); registerReceiver(usbReceiver,new IntentFilter(ACTION_USB)); } void checkUsb(){ HashMap<String,UsbDevice> list=usbManager.getDeviceList(); if(list.isEmpty()) tvUsb.setText("USB: No OTG"); else for(UsbDevice d:list.values()){ tvUsb.setText("USB Found"); PendingIntent pi=PendingIntent.getBroadcast(this,0,new Intent(ACTION_USB),PendingIntent.FLAG_MUTABLE); usbManager.requestPermission(d,pi); } } BroadcastReceiver usbReceiver=new BroadcastReceiver(){ public void onReceive(Context c,Intent i){ if(ACTION_USB.equals(i.getAction())){ boolean ok=i.getBooleanExtra(UsbManager.EXTRA_PERMISSION_GRANTED,false); tvUsb.setText(ok?"USB OK":"Denied"); } } }; void pickFile(){ Intent intent=new Intent(Intent.ACTION_GET_CONTENT); intent.setType("*/*"); startActivityForResult(intent,99); } @Override protected void onActivityResult(int req,int res,Intent data){ super.onActivityResult(req,res,data); if(req==99 && res==RESULT_OK && data!=null){ try{ InputStream is=getContentResolver().openInputStream(data.getData()); File out=new File(getCacheDir(),"flash.img"); FileOutputStream fos=new FileOutputStream(out); byte[] buf=new byte[8192]; int len; while((len=is.read(buf))>0) fos.write(buf,0,len); fos.close(); is.close(); selectedPath=out.getAbsolutePath(); tvPath.setText(selectedPath); log("> Loaded "+out.length()/1024+"KB"); } catch(Exception e){} } } void flash(String p){ if(selectedPath.isEmpty()){ log("! Pick IMG first"); return; } exec("fastboot flash "+p+" "+selectedPath); } void exec(String cmd){ log("$ "+cmd); new Thread(()->{ try{ Process pr=Runtime.getRuntime().exec(new String[]{"su","-c",cmd}); BufferedReader br=new BufferedReader(new InputStreamReader(pr.getInputStream())); BufferedReader be=new BufferedReader(new InputStreamReader(pr.getErrorStream())); String l; while((l=br.readLine())!=null){ String ll=l; runOnUiThread(()->log(ll)); } while((l=be.readLine())!=null){ String ll=l; runOnUiThread(()->log(ll)); } pr.waitFor(); runOnUiThread(()->log("> done")); } catch(Exception e){ runOnUiThread(()->log("ERR "+e.getMessage())); } }).start(); } void log(String s){ runOnUiThread(()->{ tvLog.append("\n"+s); }); } }'
open("app/src/main/java/com/otgflasher/pro/MainActivity.java","w").write(java)
